package org.urbanchaos.diagnostic;
import android.app.*;import android.os.*;import android.view.*;import android.graphics.*;import android.content.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Action IDs are diagnostic contracts; no Urban Chaos bindings are claimed. */
public final class HudActivity extends Activity {
 final String[] actions={"move","look","primary","secondary","interact","pause"};final Map<Integer,Integer> pointers=new HashMap<>();final float[][] positions={{.16f,.76f},{.78f,.76f},{.9f,.5f},{.78f,.45f},{.64f,.5f},{.5f,.12f}};String inputStatus="A=primary · B=secondary · X=interact · Start=pause";boolean edit=true;Paint paint=new Paint(3);File config;
 @Override public void onCreate(Bundle b){super.onCreate(b);config=new File(getFilesDir(),"config/hud.json");try{JSONArray a=new JSONArray(new String(Files.readAllBytes(config.toPath()),java.nio.charset.StandardCharsets.UTF_8));for(int i=0;i<actions.length;i++){positions[i][0]=clamp((float)a.getJSONObject(i).getDouble("x"));positions[i][1]=clamp((float)a.getJSONObject(i).getDouble("y"));}}catch(Exception ignored){}setContentView(new Hud(this));}
 static float clamp(float f){return Float.isFinite(f)?Math.max(.06f,Math.min(.94f,f)):.5f;}
 void save(){try{JSONArray a=new JSONArray();for(int i=0;i<actions.length;i++)a.put(new JSONObject().put("action",actions[i]).put("x",positions[i][0]).put("y",positions[i][1]));Importer.atomic(config,a.toString());}catch(Exception e){android.widget.Toast.makeText(this,e.getMessage(),android.widget.Toast.LENGTH_SHORT).show();}}
 class Hud extends View {Hud(Context c){super(c);setFocusable(true);}protected void onDraw(Canvas c){c.drawColor(Color.rgb(15,21,30));paint.setColor(Color.WHITE);paint.setTextSize(28);c.drawText("HUD diagnóstico · toque aqui: "+(edit?"EDITAR (arraste)":"TESTAR ações"),20,40,paint);c.drawText("Sem vínculo com o jogo · voltar para salvar",20,80,paint);c.drawText(inputStatus,20,115,paint);for(int i=0;i<actions.length;i++){float x=positions[i][0]*getWidth(),y=positions[i][1]*getHeight();paint.setColor(pointers.containsValue(i)?Color.GREEN:Color.rgb(40,110,155));c.drawCircle(x,y,48,paint);paint.setColor(Color.WHITE);paint.setTextSize(22);c.drawText(actions[i],x-35,y+7,paint);}}
 public boolean performClick(){super.performClick();edit=!edit;invalidate();return true;}
 public boolean onTouchEvent(MotionEvent e){int action=e.getActionMasked(),idx=e.getActionIndex(),id=e.getPointerId(idx);if(action==MotionEvent.ACTION_DOWN&&e.getY()<100){performClick();return true;}if(action==MotionEvent.ACTION_DOWN||action==MotionEvent.ACTION_POINTER_DOWN){for(int i=0;i<positions.length;i++)if(Math.hypot(e.getX(idx)-positions[i][0]*getWidth(),e.getY(idx)-positions[i][1]*getHeight())<65){pointers.put(id,i);break;}}if(action==MotionEvent.ACTION_MOVE&&edit){for(int k=0;k<e.getPointerCount();k++){Integer i=pointers.get(e.getPointerId(k));if(i!=null){positions[i][0]=clamp(e.getX(k)/getWidth());positions[i][1]=clamp(e.getY(k)/getHeight());}}}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_POINTER_UP){pointers.remove(id);save();}if(action==MotionEvent.ACTION_CANCEL)pointers.clear();invalidate();return true;}}
 @Override public boolean onGenericMotionEvent(MotionEvent e){if((e.getSource()&InputDevice.SOURCE_JOYSTICK)!=0){inputStatus="move="+e.getAxisValue(MotionEvent.AXIS_X)+","+e.getAxisValue(MotionEvent.AXIS_Y)+" look="+e.getAxisValue(MotionEvent.AXIS_Z)+","+e.getAxisValue(MotionEvent.AXIS_RZ);getWindow().getDecorView().invalidate();return true;}return super.onGenericMotionEvent(e);}
 int keyAction(int k){switch(k){case KeyEvent.KEYCODE_BUTTON_A:return 2;case KeyEvent.KEYCODE_BUTTON_B:return 3;case KeyEvent.KEYCODE_BUTTON_X:return 4;case KeyEvent.KEYCODE_BUTTON_START:return 5;default:return -1;}}
 @Override public boolean onKeyDown(int k,KeyEvent e){int i=keyAction(k);if(i<0)return super.onKeyDown(k,e);pointers.put(-k,i);inputStatus=actions[i]+"=1";getWindow().getDecorView().invalidate();return true;}
 @Override public boolean onKeyUp(int k,KeyEvent e){int i=keyAction(k);if(i<0)return super.onKeyUp(k,e);pointers.remove(-k);inputStatus=actions[i]+"=0";getWindow().getDecorView().invalidate();return true;}
 @Override protected void onPause(){pointers.clear();save();super.onPause();}
}
